const nsCharScreen=document.createElement('section');nsCharScreen.className='ns-char-screen';nsCharScreen.id='ns-char-screen';
nsCharScreen.innerHTML=`<div class="ns-char-head"><div><p class="ns-char-title">CHARACTER CODEX</p><small style="color:#b9d4ec">30 HEROES · INDIVIDUAL COMBAT PROFILES</small></div><div class="ns-char-tools"><input id="ns-char-search" aria-label="Search characters" placeholder="Search heroes..."><select id="ns-char-rarity" aria-label="Filter by rarity"><option value="all">All rarities</option><option>Legendary</option><option>Epic</option><option>Rare</option><option>Uncommon</option><option>Common</option></select><button class="ns-close" id="ns-char-back">← WORLD</button></div></div><div class="ns-char-grid" id="ns-char-grid"></div>`;
const nsProfile=document.createElement('section');nsProfile.className='ns-char-profile';nsProfile.id='ns-char-profile';nsProfile.innerHTML='<div class="ns-profile-inner" id="ns-profile-inner"></div>';
root.append(nsCharScreen,nsProfile);
const nsEsc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nsRarity={Legendary:'#f6bd55',Epic:'#c18aff',Rare:'#61bbff',Uncommon:'#79dfa8',Common:'#c5ced9'};
function nsRenderCharacters(){const query=$('ns-char-search').value.trim().toLowerCase(),rarity=$('ns-char-rarity').value;const list=NS_CHARACTERS.filter(c=>(rarity==='all'||c.rarity===rarity)&&[c.name,c.element,c.role].join(' ').toLowerCase().includes(query));$('ns-char-grid').innerHTML=list.map(c=>`<button class="ns-char-card" data-character="${c.id}" style="--glow:${nsRarity[c.rarity]}33;--rarity:${nsRarity[c.rarity]}"><div class="ns-char-art">${c.icon}</div><div class="ns-char-cardbody"><div class="ns-char-name">${nsEsc(c.name)}</div><div class="ns-char-meta"><span>${nsEsc(c.element)} · ${nsEsc(c.role)}</span><span class="ns-rarity">${c.rarity.toUpperCase()}</span></div><div class="ns-char-meta"><span>ATK ${c.attack}</span><span>HP ${c.health}</span></div><div class="ns-statbar"><span style="--value:${Math.min(100,c.attack/13)}%"></span></div></div></button>`).join('')||'<p style="grid-column:1/-1;color:#b9d4ec;text-align:center">No characters match this search.</p>'}
function nsOpenCharacter(id){const c=NS_CHARACTERS.find(x=>x.id===id);if(!c)return;const inner=$('ns-profile-inner');inner.innerHTML=`<div class="ns-profile-hero" style="--glow:${nsRarity[c.rarity]}44"><div class="ns-profile-portrait">${c.icon}</div><div class="ns-profile-copy"><div class="ns-rarity" style="color:${nsRarity[c.rarity]}">${c.rarity.toUpperCase()} · ${nsEsc(c.element.toUpperCase())}</div><h2>${nsEsc(c.name)}</h2><div class="ns-element">${nsEsc(c.role)} · COMBAT PROFILE</div><p>${nsEsc(c.bio)}</p><button class="ns-close" id="ns-profile-close">← COLLECTION</button></div></div><div class="ns-profile-body"><div class="ns-stat-grid"><div class="ns-stat"><b>${c.attack}</b><small>ATTACK DAMAGE</small></div><div class="ns-stat"><b>${c.defense}</b><small>DEFENSE</small></div><div class="ns-stat"><b>${c.health}</b><small>HEALTH</small></div><div class="ns-stat"><b>${c.range}/6</b><small>RANGE</small></div></div><div><b>ABILITIES & COMBAT ACTIONS</b><p style="color:#9fbdd8;font-size:11px;margin:5px 0 10px">Damage values are percentages of this character's attack stat unless stated otherwise. Range 1 is melee; range 6 is long-range.</p><div class="ns-abilities"><article class="ns-ability"><b>⚔ BASIC · ${nsEsc(c.basic.name)}</b><p>${nsEsc(c.basic.description)}</p><small>ATTACK · RANGE ${c.range}</small></article><article class="ns-ability"><b>✦ ULTIMATE · ${nsEsc(c.ultimate.name)}</b><p>${nsEsc(c.ultimate.description)}</p><small>ULTIMATE · RANGE ${c.range}</small></article><article class="ns-ability"><b>⬡ PASSIVE · ${nsEsc(c.passive.name)}</b><p>${nsEsc(c.passive.description)}</p><small>PASSIVE · ALWAYS ACTIVE WHEN CONDITIONS APPLY</small></article><article class="ns-ability"><b>◈ DEFENSE PROFILE</b><p>${nsEsc(c.role)} · ${c.defense} defense · ${c.health} health. Defensive actions and resistance are described in the ability text.</p><small>CLASS · ${nsEsc(c.element.toUpperCase())}</small></article></div></div></div>`;nsProfile.classList.add('open');$('ns-profile-close').onclick=()=>nsProfile.classList.remove('open')}
$('ns-char-grid').addEventListener('click',e=>{const b=e.target.closest('[data-character]');if(b)nsOpenCharacter(b.dataset.character)});
$('ns-char-search').addEventListener('input',nsRenderCharacters);$('ns-char-rarity').addEventListener('change',nsRenderCharacters);
$('ns-char-back').onclick=()=>nsCharScreen.classList.remove('open');
function nsOpenCharacterCollection(){nsCharScreen.classList.add('open');nsProfile.classList.remove('open');nsRenderCharacters()}

root.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{sound(430);if(b.dataset.nav==='Characters'){nsOpenCharacterCollection()}else{alert(b.dataset.nav+' screen is ready to connect to the game systems.')}});


 // Real-time 3D PBR world layer. "4D" is not a standard model format;
 // this uses actual 3D geometry, physically-based materials and animated time-based effects.
 const mapEl=root.querySelector('.map'), oldMap=mapEl.querySelector('svg');
